function attentionForAttempt(attempt,status){var reasons=[];if(!attempt)return reasons;if(attempt.pending_requests&&attempt.pending_requests.length)reasons.push("pending_interaction");if(attempt.reply_outcome_unknown_requests&&attempt.reply_outcome_unknown_requests.length)reasons.push("interaction_reply_outcome_unknown");if(attempt.cleanup&&attempt.cleanup.state==="pending")reasons.push("cleanup_pending");if(attempt.cleanup&&attempt.cleanup.state==="unverified")reasons.push("cleanup_unverified");if(attempt.hold&&attempt.hold.active)reasons.push("hold:"+(attempt.hold.reason_code||"hold"));if(attempt.wake&&attempt.wake.state==="submission_unknown")reasons.push("wake_submission_unknown");if(attempt.wake&&attempt.wake.state==="web_notify")reasons.push("wake_web_notify");if(attempt.result&&attempt.result.needs_master_decision)reasons.push("needs_master_decision");if(status==="waiting_for_master")reasons.push("waiting_for_master");if(status==="failed")reasons.push("task_failed");return reasons;}
